async function readApps(){if(typeof window.omnibloomHost?.getApps==='function')return await window.omnibloomHost.getApps();throw Error('Apps unavailable')}
function notify(message){obUI.toast(message)}
async function openApp(id){if(window.omnibloomHost&&typeof window.omnibloomHost.openApp==='function'){try{await window.omnibloomHost.openApp(id);notify(StartI18n.t('Open request sent.'))}catch(e){notify(StartI18n.t('Could not open this app. Try again.'))}}else notify(StartI18n.t('Preview only. App launch needs the Omni bridge.'));}

function safeURL(value){try{return PinsModel.url(value)}catch{return null}}
let recents=[];try{const v=JSON.parse(localStorage.getItem('ob.recents')||'[]');if(Array.isArray(v))recents=v.filter(x=>x&&safeURL(x.url)).slice(0,5)}catch{}
function saveRecents(){try{localStorage.setItem('ob.recents',JSON.stringify(recents))}catch{notify(StartI18n.t('Recent sites could not be saved.'))}}
function renderRecents(){const box=document.getElementById('recents');box.replaceChildren();for(const item of recents){const b=document.createElement('button');b.textContent=item.name||new URL(item.url).hostname;b.onclick=()=>visit(item.url);box.append(b)}if(!box.children.length)box.textContent=StartI18n.t('Sites opened here appear on this device.')}
async function visit(value){const url=safeURL(value);if(!url)return;try{if(window.omnibloomHost){if(typeof omnibloomHost.request!=='function')throw Error('Unavailable');const reply=await omnibloomHost.request({version:1,id:'start-'+crypto.randomUUID(),method:'navigation.open',params:{url}});if(reply?.ok!==true)throw Error(reply?.code||'Unavailable')}else location.href=url;recents=[{name:new URL(url).hostname,url},...recents.filter(x=>x.url!==url)].slice(0,5);saveRecents();renderRecents()}catch{notify(StartI18n.t('This site could not open. Try again.'))}}
document.getElementById('clear-recents').onclick=()=>{recents=[];saveRecents();renderRecents();notify(StartI18n.t('Recent sites cleared on this device.'))};renderRecents();
document.getElementById('search').onsubmit=async e=>{e.preventDefault();const q=document.getElementById('query').value.trim();if(!q)return;if(typeof window.omnibloomHost?.search==='function'){try{await window.omnibloomHost.search(q)}catch{notify(StartI18n.t('Search could not open. Try again.'))}return}const url=safeURL(q)||(q.includes('.')&&!q.includes(' ')?safeURL('https://'+q):null);visit(url||'https://duckduckgo.com/?q='+encodeURIComponent(q))};
const templates={'universe.day':StartI18n.t('Universe of the day · %s'),'universe.selected':StartI18n.t('Your universe · %s')};function universeText(key,name){let template=templates[key];try{const translated=window.omnibloomHost?.translate?.(key,template);if(typeof translated==='string'&&translated.includes('%s'))template=translated}catch(e){}return template.replace('%s',name)}
const picker=document.getElementById('universe-picker');obUniverses.ids.forEach(id=>picker.add(new Option(obUniverses.label(id),id)));function showUniverse(id,chosen){picker.value=id;document.getElementById('universe-day').textContent=universeText(chosen?'universe.selected':'universe.day',obUniverses.label(id));document.getElementById('universe-day').dataset.i18n=chosen?'universe.selected':'universe.day';document.querySelector('.hero').className='hero universe-hero universe-'+id}let userChanged=false;picker.onchange=()=>{userChanged=true;showUniverse(picker.value,true);obUniverses.write(picker.value)};obUniverses.read().then(id=>{if(!userChanged)showUniverse(id||obUniverses.ids[Math.floor(Date.now()/86400000)%15],!!id)});window.addEventListener('storage',e=>{if(e.key==='ob.universe'){const id=obUniverses.normalize(e.newValue);if(id)showUniverse(id,true)}});
readApps().then(data=>{const box=document.getElementById('apps');(Array.isArray(data)?data:data.apps||[]).slice(0,4).forEach(app=>{const b=document.createElement('button');b.className='tile';const title=document.createElement('b'),status=document.createElement('span');title.textContent=app.name;status.textContent=app.up?StartI18n.t('Running'):StartI18n.t('Ready to open');b.append(obAppIcon(app.id),title,status);b.onclick=()=>openApp(app.id);box.append(b)});if(!box.children.length)box.textContent=StartI18n.t('No apps installed yet.')}).catch(()=>{document.getElementById('apps').textContent=StartI18n.t('App list unavailable. You can still browse.')});
